$s->mutate(1,false,'save_note',['id'=>$n['id'],'title'=>'Edited','content'=>'Updated','revision'=>$n['revision']]);rejects(fn()=>$s->mutate(1,false,'save_note',['id'=>$n['id'],'title'=>'Stale','content'=>'Stale','revision'=>$n['revision']]),409);
